INSERT INTO `surrogacyclinic` (`id`, `directorname`, `fax`, `website`, `dateestab`, `mtpact`, `pcpndtact`, `director`, `otherstaff`, `equipment`, `iuih`, `iuid`, `ivfet`, `icsi`, `pgt`, `spermandoocyte`, `anyotherprocedure`, `otherprocedure`, `otherdetails`, `status`, `appstatus`, `comment`, `userid`, `datetime_decision`) VALUES
(249, '', '04512430088', 'www.avfchospital.com', '25/08/2013', 'Yes', 'Yes', 'Yes', '', '', 'Yes', 'Yes', 'Yes', 'Yes', 'Yes', 'Yes', 'Yes', 'Laser Assisted Hatching', 'Percutaneous Epididymal Sperm Aspiration(PESA), Testicular Sperm Aspiration(TESA), Testicular Sperm Extraction(TESE), Blastocyst\r\nSeparation Techinique, Endometrial Receptivity Array. MALE FACTOR: a.Treatment of oligozoospermia, b.Detecting infection of the\r\nreproductive tract using appropriate diagnostic test, c.Immunological test for infertility, d.Provision for semen collection in men with a vibrator\r\nor an Electroejaculator in erectile dysfunction and ejaculatory problems, e.Karyotyping. FEMALE FACTOR: a.Treatment of minor anatomical\r\ndefects like imperforate hymen, b.Treatment of endometriosis after confirming its presence by diagnostic laparoscopy, c.Induction of ovulation\r\nin anovulatory women with drugs such as Clomiphene citrate etc., d.Correcting endocrine disorders such as Thyroid disorders,\r\nHyperprolactinemia, e.Detecting infection of the reproductive tract using appropriate diagnostictest. Conservative surgery : Laparoscopy,\r\nHysteroscopy Combined medical - surgical theraphy a co-ordinated team, for example in endometriosis, Assessment of follicular growth and\r\novulation by serial ultrasonography, Immunological test for infertility, Assessment of follicular growth and ovulation by serial transvaginal\r\nsonography(TVS), Provision for extended treatment of infertiity except for oocyte pick up, Karyotyping,Saline sono salphingography,\r\nHysterosalpingogram(HSG) ANDROLOGY:Basic investigation such as physical examination and semen analysis as per WHO method,\r\nAdvanced Sperm Function test like hypo-osmotic swelling test(HOST), Test for sperm function and integrity such as acrosome reaction and\r\nsperm-oocyte interaction in-vitro.	', 1, 'Pending', NULL, 721, '2022-05-21 07:58:10'),
