INSERT INTO `update_signup_details` (`id`, `email_id`, `request_details`, `update_request_date`, `status`, `datetime`) VALUES
(1, 'atimrana07@gmail.com', 'jffjfj', '2022-05-05', 1, '2022-05-27 11:25:36'),
(2, 'atimrana07@gmail.com', 'mvmckncjcc', '2022-05-05', 1, '2022-05-27 11:28:05'),
(3, 'bharathifertility@gmail.com', 'I want to edit the name of our centre . It has been typed as Bharathi Advanced Fertility and Research Centre instead of Bharathi Advanced Fertility and Women\'s Centre. Now I\'m not able to edit it . Kindly guide me regarding this . ', '2022-04-26', 1, '2022-05-30 05:22:44'),
(4, 'manjirizende@gmail.com', 'We have successfully created account for ART registration of Zende Hospital,by Dr Manjiri Prashant Zende.\r\nBut by mistake in  personal information section the name  of Health facility section it was written ART Clinic,and we want to change it as\r\n\' Zende Hospital and Dr Zende\'s Test Tube Baby Centre. \' \r\nEnclosed herewith screenshot of personal information form.\r\nKindly rectify it.', '2022-05-02', 1, '2022-05-30 05:33:20'),
(5, 'drrajanvaidya@yahoo.co.uk', 'Thank you for your prompt and quick response. We wish to make few more corrections in our application form. Kindly guide us how we can edit our application form?\r\n\r\nThanks for your mail. Sir, we need to make some changes in our application form ( Application No.: TN/AC/2022/10061). Kindly advice how to edit our application form. Looking forward to hearing from you.', '2022-05-05', 0, '2022-05-30 05:36:14'),
(6, 'extolseed2018@gmail.com', 'As below was the registration process did on April 22 and account was created successfully.\r\nBut\r\nLater I noticed that in the \'Name of Health facility\' I had to put my centre\'s name that is \'EXTOLSEED ART BANK\'\r\nBut\r\nI can\'t edit that field anymore.\r\n\r\nSo please edit that\r\nSo I can complete the rest part of registration.', '2022-05-13', 1, '2022-05-30 05:43:16'),
(7, 'drrajanvaidya@yahoo.co.uk', 'My name is Dr Rajan Vaidya. I have submitted the below applications\r\nART Clinic - MH/AC/2022/10172\r\nSurrogacy Clinic - MH/SC/2022/10038\r\nMy username is drrajanvaidya@yahoo.co.uk\r\nAfter submission, I discovered that there are some typing errors in the both the applications. The online profile is not allowing me to edit/modify my applications and profile.\r\n\r\nCan you please advice on the next steps to modify my applications? Is there an option to edit the applications or should we create a new profile and resubmit?', '2022-05-04', 0, '2022-05-30 05:53:02'),
(8, 'info@drmalpani.com', 'Sir/ Madam, \r\nWe had made a profile of our ART Clinic on the website for the National Art and Surrogacy Registry. and filled out all the forms as well.\r\n\r\nBut all of a sudden, the clinic\'s name, address, and phone number disappeared from the profile page, and we can\'t fix it. We\'ve included a screenshot for you to look at.\r\n\r\nPlease check this from your end and help us figure out how to fix this.\r\n\r\nWaiting for your reply.', '2022-05-25', 0, '2022-05-30 06:48:46'),
(9, 'rashmikafertility@gmail.com', 'Email received for correction profile details.', '2022-05-27', 1, '2022-05-30 06:56:48'),
(10, 'mehuldamani1@gmail.com', 'Email received for correction in profile details.', '2022-05-27', 1, '2022-05-30 06:58:41'),
(11, 'bhoomi.ivf@gmail.com', 'Dear sir,\r\nI have submitted the form as ART clinic in the national registry. But I need to do some corrections in the application form. Kindly guide us.\r\n\r\nART Application Number KA/AC/2022/10052\r\n\r\nCORRECTIONS REQUIRED ARE\r\n1] To put name of the contact person instead of phone number\r\n    Dr. G. Kasturi', '2022-04-26', 1, '2022-06-02 04:24:42'),
(12, 'Arthyd.legal@artfertilityclinics.com', 'Dear Sir,\r\n\r\n \r\n\r\nAs discussed, request you to change the profile details as mentioned below:\r\n\r\n \r\n\r\nEmail id: Arthyd.legal@artfertilityclinics.com\r\n\r\nName of clinic: Art Fertility Clinics, a unit of Global Fertility Solutions Private Limited\r\n\r\nAddress: 2nd & 3rd floor, Heera Moti Complex, Plot No - 8-2-293/82/A), Jubilee Hills, Hyderbad-500033', '2022-05-30', 1, '2022-06-02 04:35:24'),
(13, 'atimrana07@gmail.com', 'hello', '2022-06-02', 1, '2022-06-02 04:53:16'),
(14, 'atimrana07@gmail.com', 'dcdsfcs', '2022-06-02', 1, '2022-06-02 10:50:30'),
(15, 'Ramasubramanian_k@apollohospitals.com', ' Dear Sir,\r\n\r\nAfter long try, we could able to login for Apollo Women\'s Hospital. But in the profile details, our hospital name not reflecting ( Login ID - Ramasubramanian_k@apollohospitals.com)\r\n\r\nKindly do the needful to update the Hospital name as APOLLO WOMEN\'S HOSPITAL and address as No.16, Shafee Mohammed Road, Thousand Lights, Chennai - 600 006.\r\n\r\nWe are in the process of completing the application for NART with all relevant details. Kindly do the needful.', '2022-06-03', 1, '2022-06-06 07:31:51'),
(16, 'Ramasubramanian_k@apollohospitals.com', ' Dear Sir,\r\n\r\nAfter long try, we could able to login for Apollo Women\'s Hospital. But in the profile details, our hospital name not reflecting ( Login ID - Ramasubramanian_k@apollohospitals.com)\r\n\r\nKindly do the needful to update the Hospital name as APOLLO WOMEN\'S HOSPITAL and address as No.16, Shafee Mohammed Road, Thousand Lights, Chennai - 600 006.\r\n\r\nWe are in the process of completing the application for NART with all relevant details. Kindly do the needful.', '2022-06-03', 1, '2022-06-06 12:23:24'),
(17, 'art.indlegal@artfertilityclinics.com', 'Dear Sir,\r\nWe are trying to file Art and surrogacy application, however the data in our profile is missing. Below is the screen shot for your reference.\r\nRequest you to kindly help to resolve this issue. ', '2022-06-07', 0, '2022-06-08 03:28:07'),
(18, 'drlavleen@gmail.com', 'Dear Sir / Madam\r\nI had signed up in order to register our centre on 30th of May, 2022 \r\nlogin credentials are:\r\nUser ID: drlavleen@gmail.com\r\nPassword:sanlav@152425.\r\nThe name of the centre filled at the time of sign-up and creation of link for registration was incorrectly filled as â€™Dr Sodhi Health Careâ€™. The actual complete name of the centre is â€˜Dr Sodhiâ€™s Health Care, Multispeciality Hospital & IVF Centreâ€™.\r\n\r\n Kindly advise us as how to make the required change.\r\nRegards\r\n\r\nDr Lavleen Kaur Sodhi', '2022-06-06', 1, '2022-06-08 03:31:06'),
(19, 'mrdmld@cloudninecare.com', 'Dear Sir/Madam,\r\nWe Kids Clinic India limited Cloudnine Fertility. With reference to the above subject we have created the ID and password for our clinics. \r\nThere is a spelling correction in the Name of the Clinic column as mentioned below. Requesting your good office please do the needful.\r\nCorrections to be made,\r\n1. Last word should be corrected as Fertility instead of Feritility.\r\n    Username - mrdmld@cloudninecare.com. Password -Mld@12345 ', '2022-06-06', 1, '2022-06-08 03:32:43'),
(20, 'mrdomr@cloudninecare.com', 'Dear Sir/Madam,\r\nWe Kids Clinic India limited Cloudnine Fertility. With reference to the above subject we have created the ID and password for our clinics. \r\nThere is a spelling correction in the Name of the Clinic column as mentioned below. Requesting your good office please do the needful.\r\nCorrections to be made,\r\n1. Last word should be corrected as Fertility instead of Feritility.\r\n2. Last word should be corrected as Fertility instead of Fertiltiy\r\n    Username -  mrdomr@cloudninecare.com  . Password -Omr@2021', '2022-06-06', 1, '2022-06-08 03:33:25'),
(21, 'Arthyd.legal@artfertilityclinics.com', 'Dear Sir,\r\nAs discussed, request you to change the profile details as mentioned below:\r\nEmail id: Arthyd.legal@artfertilityclinics.com\r\nName of clinic: Art Fertility Clinics, a unit of Global Fertility Solutions Private Limited\r\nAddress: 2nd & 3rd floor, Heera Moti Complex, Plot No - 8-2-293/82/A), Jubilee Hills, Hyderbad-500033', '2022-05-30', 1, '2022-06-09 04:21:13'),
(22, 'mrdnoida@cloudninecare.com', 'Dear Sir,\r\nThank you for the quick response, We have done the corrections.\r\nAlso we have one more spelling correction in the address column of one of our ART clinic ID. Details mentioned below for your reference. Please allow us to correct the same.\r\nCorrections to be made,\r\n1. The word should be corrected as Nagar instead of Nager in the address column.\r\nUsername -  mrdnoida@cloudninecare.com . Password - Noida@123  ', '2022-06-08', 0, '2022-06-09 04:23:21'),
(23, 'IVF@apollohospitalsdelhi.com', 'Hello Sir/Ma\'am,\r\nThis mail of mine is in regards to correcting typing error in our application form.\r\nCan I please request you to change the adress in profile section Indraprastha Apollo Hospitals, Saita Vihar, Delhi- Mathura road, New Delhi to correct address which is Indraprastha Apollo Hospitals, Sarita Vihar, Delhi-Mathura Road, New Delhi. \r\nThank you so much.\r\nThank you and regards,\r\nHarsh Kalra.\r\nSr. Embryologist\r\nIndraprastha Apollo. ', '2022-06-15', 1, '2022-06-20 04:48:25'),
(24, 'wecare@globalivffertility.com', 'Dear Sir/Madam,\r\nGreetings from Global IVF and Fertility Center!\r\nPlease note in our Application form for ART Clinic Level 1 - No. \r\nMH/AC/2022/11503 there has been a typographical error in the Mobile \r\nNumber.   Kindly do the correction of the Mobile number to 9833401240\r\nand oblige.\r\nKind Regards,\r\nRamona D\'souza\r\nPatient Co-ordinator\r\nGlobal IVF & Fertility Center\r\nShilpin Centre,\r\nUnit No. 1, Ground Floor,\r\nPlot No. 40, G.D. Ambekar Road,\r\nWadala (West),\r\nMumbai - 400 031', '2022-06-21', 0, '2022-06-21 11:34:15'),
(25, 'sushma.citt@gmail.com', 'To, \r\nThe Authority,\r\nAssisted Reproductive Technology (Regulation) Act 2021 & the Surrogacy (Regulation) Act 2021 \r\nSubject :- 1) Submission of Application for ART clinic - Level 2 \r\n                 2) Correction of the Name of IVF Center \r\nDear Sir/ Madam,\r\n           \r\n            The Name of my center is Central India Test Tube Baby Center. I filled up the application form on 13/6/2022. Before submitting the form I checked it again. I found that I have written Central India Test Tube Center instead of Central India Test Tube Baby Center.\r\n          So I tried for two hours to add the word Baby but I couldn\'t.  I tried for technical help also. But I couldn\'t add the word Baby in it.I tried to fill up the form again. But all efforts were in vain. Finally I submitted the form with the name Central India Test Tube Center. And immediately the form was accepted.   \r\n          So I request you to add one word Baby. So the correct Name of my center is  Central India Test Tube Baby Center.\r\nOr if it is not possible then how to go ahead ? \r\n          Please do the needful. \r\n\r\nRegards,\r\nDr. Sushma Deshmukh\r\nDirector - Central India Test Tube Baby Center\r\nHOD - Ob-Gy Dpt. - Getwell Multispeciality Hospital & Research Center\r\nIn charge of Deshmukh Hospital, Nagpur.\r\nMob. No. 9422103443', '2022-06-21', 1, '2022-06-23 10:27:22'),
(26, 'aasinfertilitycentre@yahoo.co.in', 'Respected Sir,\r\nPlease change the name AAS FERTILTY & METERNITYCENTRE  to AAS FERTILITY & MATERNITY CENTRE.\r\nThank you\r\nRegards\r\nDr.Rakhee Malhotra', '2022-06-23', 1, '2022-06-23 10:29:35'),
(27, 'swetapatelivf@gmail.com', 'RESPECTED SIR/MAM\r\nhere  we need guidance regarding name of health facility . while filling online registration form by mistake auto correction of healthfacility  name is ART CLINIC . WHILE OUR HOSPITAL NAME IS FEMALE FIRST HOSPITAL. SO KINDLY GUIDE FOR THE SAME.\r\nAPPLICATION NO. FOR ART CLINIC IS  [ GJ/AC/2022/10787 ]\r\nAPPLICATION NO. FOR SURROGACY IS [GJ/SC/2022/10425 ] .\r\nKINDLY GUIDE HOW TO PROCEED', '2022-06-29', 1, '2022-07-01 04:36:18'),
(28, 'jeevanmithraivf@gmail.com', 'Regarding the Change of website address in application form.\r\nAs we have mentioned our website address in the application form wrongly please consider this as an emergency and change the website address \r\ngiven website address : www.jeevanmithraivfcentre.com\r\nWebsite need to be changed: www.jeevanmithrafertilitycentre.com', '2022-06-23', 1, '2022-07-05 09:17:21'),
(29, 'drmanishamittal@yahoo.com', 'Name, address and nature have to update.', '2022-07-07', 1, '2022-07-07 04:36:16'),
(30, 'atimrana07@gmail.com', 'please change address', '2022-07-07', 1, '2022-07-07 06:42:33'),
(31, 'drmanishamittal@yahoo.com', 'update the name, address and nature of the organisation.', '2022-07-07', 1, '2022-07-07 06:44:58'),
